```python
class Vote:
    def __init__(self, candidate, votes=0):
        self.candidate = candidate
        self.votes = votes

def collect_votes(voters):
    """
    投票を収集し、Voteオブジェクトのリストを返す
    """
    votes = {}
    for voter in voters:
        if voter in votes:
            votes[voter].votes += 1
        else:
            votes[voter] = Vote(voter)
    return list(votes.values())

def count_votes(votes):
    """
    投票を集計し、候補者ごとの投票数を返す
    """
    return sorted(votes, key=lambda x: x.votes, reverse=True)

def main():
    # 投票者リスト（候補者名と投票数）
    voters = [
        ("候補者A", 150),
        ("候補者B", 120),
        ("候補者C", 80),
        ("候補者D", 50)
    ]

    # 投票を収集
    vote_list = collect_votes(voters)
    print("投票結果:")
    for candidate in vote_list:
        print(f"{candidate.candidate}: {candidate.votes} 票")

    # 投票を集計
    top_candidates = count_votes(vote_list)
    print("\n集計結果:")
    for i, candidate in enumerate(top_candidates, start=1):
        print(f"{i}. {candidate.candidate}: {candidate.votes} 票")

if __name__ == "__main__":
    main()
```

