// テスト用変数
const testURL = 'http://yourwebsite.com/test-page'; // テストするページのURL
const maintenancePageURL = 'http://yourwebsite.com/maintenance'; // メンテナンスページのURL

// ページが読み込まれたときのイベントリスナーを設定
window.addEventListener('load', function() {
    // テストURLと現在のURLを比較
    if (window.location.href === testURL) {
        // メンテナンスモードを有効にする
        enableMaintenanceMode();
    }
});

// メンテナンスモードを有効にする関数
function enableMaintenanceMode() {
    // スタイルを適用してメンテナンスページの表示をシミュレート
    document.body.style.backgroundColor = 'lightgray';
    document.body.style.fontSize = '20px';
    document.body.style.textAlign = 'center';
    document.body.innerHTML = `
        <h1>メンテナンス中...</h1>
        <p>このサイトは現在メンテナンス中です。<br>しばらくしてから再度お試しください。</p>
    `;

    // 3秒後にリダイレクト（例として）
    setTimeout(function() {
        window.location.href = maintenancePageURL;
    }, 3000);
}
